effect.shader:
vec2 getResolution(){
vec2 s = inputImg.size;
if (s.x <= 0.0 || s.y <= 0.0) s = vec2(1920.0, 1080.0);
return s;
}
float gray(vec4 c){ return dot(c.rgb, vec3(0.299,0.587,0.114)); }
mat2 rot2(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }
float getLuma(vec2 uv) {
return gray(texture2DCv(inputImg.texture, uv));
}
float sobel(vec2 uv, vec2 pixel, float w) {
vec2 p = pixel * w;
float t00 = getLuma(uv + p * vec2(-1, -1));
float t10 = getLuma(uv + p * vec2( 0, -1));
float t20 = getLuma(uv + p * vec2( 1, -1));
float t01 = getLuma(uv + p * vec2(-1,  0));
float t21 = getLuma(uv + p * vec2( 1,  0));
float t02 = getLuma(uv + p * vec2(-1,  1));
float t12 = getLuma(uv + p * vec2( 0,  1));
float t22 = getLuma(uv + p * vec2( 1,  1));
float gx = t00 + 2.0 * t01 + t02 - (t20 + 2.0 * t21 + t22);
float gy = t00 + 2.0 * t10 + t20 - (t02 + 2.0 * t12 + t22);
return length(vec2(gx, gy));
}
void main(){
vec2 res = getResolution();
vec2 uv = acScreenNorm;
vec2 pixel = 1.0 / res;
float ang = radians(stripeDirDeg);
vec2 dir = rot2(ang) * vec2(1.0, 0.0);
float edge = sobel(uv, pixel, edgeWidth) * edgeAmt;
float maskEdge = clamp(edge, 0.0, 1.0);
if(edgeInvert) maskEdge = 1.0 - maskEdge;
vec4 s0 = texture2DCv(inputImg.texture, uv);
float amp = gray(s0);
float basePhase = phaseStart + acTime * phaseSpeed + offset;
float mag = stripeMag;
float wave = dot(uv - 0.5, dir) * mag + basePhase;
wave += edge * edgeWarp;
wave += amp * edgeWarp * 0.5;
float fBase = freqColors;
float rC = 0.5 + 0.5 * sin(wave * fBase * freqRed + phaseRed);
float gC = 0.5 + 0.5 * sin(wave * fBase * freqGreen + phaseGreen);
float bC = 0.5 + 0.5 * sin(wave * fBase * freqBlue + phaseBlue);
vec3 colS = vec3(rC, gC, bC);
vec3 tint = tintColor.rgb;
vec3 colT = colS * tint;
if(!edgeInvert) {
colT *= (1.0 - maskEdge * 0.8);
} else {
colT += maskEdge * 0.5;
}
float g = dot(colT, vec3(0.299,0.587,0.114));
vec3 colSat = mix(vec3(g), colT, clamp(saturation, 0.0, 2.0));
colSat *= brightness;
vec3 srcCol = s0.rgb;
float aIn = s0.a;
vec3 stripeBlend = mix(colSat, srcCol, mixWithSource);
vec3 outCol = mix(srcCol, stripeBlend, aIn);
gl_FragColor = vec4(outCol, aIn);
}
